<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Asset checkout signature</title><style>body{font-family:Arial;background:#f1f7ef;color:#234222;margin:0;padding:24px}.card{max-width:720px;margin:auto;background:white;border:1px solid #d8e7d4;border-radius:22px;padding:24px}table{width:100%;border-collapse:collapse;margin:20px 0}td{padding:10px;border-bottom:1px solid #e5eee3}canvas{width:100%;height:180px;border:1px solid #aac4a4;border-radius:12px;touch-action:none}.actions{display:flex;gap:10px;margin-top:16px}button{padding:11px 18px;border:0;border-radius:999px;font-weight:bold;cursor:pointer}.submit{background:#4f9f4a;color:white}.clear{background:#edf5eb;color:#315c2e}.notice{padding:12px;border-radius:10px;background:#edf7ea;margin-bottom:16px}</style></head><body><div class="card"><h1>Asset Checkout Form</h1><p>Please review the asset details and sign below.</p>@if($preview ?? false)<div class="notice">This is a test preview. It will not create or change an asset checkout.</div>@endif<table><tr><td>Asset tag</td><td>{{ $assignment->asset->asset_tag_no }}</td></tr><tr><td>Description</td><td>{{ $assignment->asset->description ?: $assignment->asset->model }}</td></tr><tr><td>Serial number</td><td>{{ $assignment->asset->serial_no ?: '-' }}</td></tr><tr><td>Staff</td><td>{{ $assignment->assigned_to_name }}</td></tr><tr><td>Employee ID</td><td>{{ $assignment->employee_id ?: '-' }}</td></tr><tr><td>Department</td><td>{{ $assignment->department ?: '-' }}</td></tr><tr><td>Checkout date</td><td>{{ $assignment->assigned_at?->format('Y-m-d') }}</td></tr></table>@if($preview)<p class="notice">Signature submission is disabled for this preview.</p>@else<form method="post" action="{{ route('public.asset-checkout.sign', $token) }}">@csrf<label><strong>Digital signature *</strong></label><canvas id="pad"></canvas><input type="hidden" name="signature" id="signature"><div class="actions"><button class="clear" type="button" id="clear">Clear</button><button class="submit" type="submit">Sign and submit</button></div></form>@endif</div>@if(!($preview ?? false))<script>const c=document.getElementById('pad'),x=c.getContext('2d');function size(){c.width=c.clientWidth*devicePixelRatio;c.height=c.clientHeight*devicePixelRatio;x.scale(devicePixelRatio,devicePixelRatio);x.lineWidth=2;x.lineCap='round'}size();let drawing=false;const point=e=>{const r=c.getBoundingClientRect();return[e.clientX-r.left,e.clientY-r.top]};c.onpointerdown=e=>{drawing=true;x.beginPath();x.moveTo(...point(e))};c.onpointermove=e=>{if(drawing){x.lineTo(...point(e));x.stroke()}};c.onpointerup=()=>drawing=false;document.getElementById('clear').onclick=()=>x.clearRect(0,0,c.width,c.height);document.querySelector('form').onsubmit=()=>{document.getElementById('signature').value=c.toDataURL('image/png');return document.getElementById('signature').value.length>100};</script>@endif</body></html>
